    76→  public Bytes4 computeForkVersion(final UInt64 epoch) {
    77→    if (epoch.isGreaterThanOrEqualTo(specConfig.getGloasForkEpoch())) {
    78→      return specConfig.getGloasForkVersion();
    79→    } else if (epoch.isGreaterThanOrEqualTo(specConfig.getFuluForkEpoch())) {
    80→      return specConfig.getFuluForkVersion();
    81→    } else if (epoch.isGreaterThanOrEqualTo(specConfig.getElectraForkEpoch())) {
    82→      return specConfig.getElectraForkVersion();
    83→    } else if (epoch.isGreaterThanOrEqualTo(specConfig.getDenebForkEpoch())) {
