    95→  public int computeShuffledIndex(final int index, final int indexCount, final Bytes32 seed) {
    96→    checkArgument(index < indexCount, "CommitteeUtil.computeShuffledIndex1");
    97→
    98→    final Sha256 sha256 = getSha256Instance();
    99→
   100→    int indexRet = index;
   101→    final int shuffleRoundCount = specConfig.getShuffleRoundCount();
   102→
   103→    for (int round = 0; round < shuffleRoundCount; round++) {
   104→
   105→      Bytes roundAsByte = Bytes.of((byte) round);
   106→
   107→      // This needs to be unsigned modulo.
   108→      int pivot =
   109→          bytesToUInt64(sha256.wrappedDigest(seed, roundAsByte).slice(0, 8))
   110→              .mod(indexCount)
   111→              .intValue();
   112→      int flip = Math.floorMod(pivot + indexCount - indexRet, indexCount);
   113→      int position = Math.max(indexRet, flip);
   114→
   115→      Bytes positionDiv256 = uintTo4Bytes(Math.floorDiv(position, 256L));
   116→      byte[] hashBytes = sha256.digest(seed, roundAsByte, positionDiv256);
   117→
   118→      int bitIndex = position & 0xff;
   119→      int theByte = hashBytes[bitIndex / 8];
   120→      int theBit = (theByte >> (bitIndex & 0x07)) & 1;
   121→      if (theBit != 0) {
   122→        indexRet = flip;
   123→      }
   124→    }
   125→
   126→    return indexRet;
   127→  }
