   237→  private IntList computeCommitteeShuffle(
   238→      final BeaconState state,
   239→      final IntList indices,
   240→      final Bytes32 seed,
   241→      final int fromIndex,
   242→      final int toIndex) {
   243→    if (fromIndex < toIndex) {
   244→      final int indexCount = indices.size();
   245→      checkArgument(fromIndex < indexCount, "CommitteeUtil.getShuffledIndex1");
   246→      checkArgument(toIndex <= indexCount, "CommitteeUtil.getShuffledIndex1");
   247→    }
   248→    return BeaconStateCache.getTransitionCaches(state)
   249→        .getCommitteeShuffle()
   250→        .get(seed, s -> shuffleList(indices, s))
   251→        .subList(fromIndex, toIndex);
   252→  }
