    65→  @Override
    66→  public SafeFuture<GetPayloadResponse> execute(final JsonRpcRequestParams params) {
    67→    final ExecutionPayloadContext executionPayloadContext =
    68→        params.getRequiredParameter(0, ExecutionPayloadContext.class);
    69→    final UInt64 slot = params.getRequiredParameter(1, UInt64.class);
    70→
    71→    LOG.trace(
    72→        "Calling {}(payloadId={}, slot={})",
    73→        getVersionedName(),
    74→        executionPayloadContext.getPayloadId(),
    75→        slot);
    76→
    77→    return executionEngineClient
    78→        .getPayloadV5(executionPayloadContext.getPayloadId())
    79→        .thenApply(ResponseUnwrapper::unwrapExecutionClientResponseOrThrow)
    80→        .thenApply(
    81→            response -> {
    82→              final SchemaDefinitions schemaDefinitions = spec.atSlot(slot).getSchemaDefinitions();
    83→              final ExecutionPayloadSchema<?> payloadSchema =
    84→                  SchemaDefinitionsBellatrix.required(schemaDefinitions)
    85→                      .getExecutionPayloadSchema();
