    87→                  response.executionPayload.asInternalExecutionPayload(payloadSchema);
    88→              final BlobsCellBundle blobsCellBundle =
    89→                  getBlobsCellBundle(response, schemaDefinitions);
    90→              final ExecutionRequests executionRequests =
    91→                  executionRequestsDataDecoder.decode(response.executionRequests);
    92→              return new GetPayloadResponse(
    93→                  executionPayload,
    94→                  response.blockValue,
    95→                  blobsCellBundle,
    96→                  response.shouldOverrideBuilder,
    97→                  executionRequests);
    98→            })
    99→        .thenPeek(
   100→            getPayloadResponse ->
